    hp(d,'narbo',{kind:'battle',left:1,note:'507年后的临时王都；531年阿马拉里克在城下败给法兰克人。'});
    hp(d,'k_barcelona',{note:'6世纪前期王廷一度设在这里。'});
    hp(d,'toletum',{note:'6世纪中叶起王廷常驻于此。'});
    hr(d,[[46.64,0.17],[45.2,0.9],[43.6,1.44]],HC.myc);
