    hp(d,'recopolis',{note:'578年莱奥维吉尔德新建，以次子雷卡雷德的名字命名。'});
    hp(d,'hispalis',{kind:'battle',left:1,note:'579年长子赫尔梅内吉尔德在此造反，583—584年被父亲围攻。'});
