    hp(d,'k_frankfurt',{note:'1007年11月1日的会上，亨利二世立基督为继承人，准设班贝格主教区。'});
    hp(d,'ic_bamberg',{note:'亨利二世最喜欢的城，本是给皇后的嫁妆；1007年设主教区，夫妻都葬在这里的大教堂。'});
