    hp(d,'fr_rouen',{left:1,note:'诺曼底公爵都城；911年糊涂查理割给维京人的地盘已长成强藩。'});
    hp(d,'w_bordeaux',{left:1,note:'阿基坦公国重镇，幅员比卡佩王领大数倍。'});
