    hp(d,'pl_dijon',{note:'勃艮第公国：叛逆的王太子路易在1456—1461年间躲在勃艮第公爵好人腓力庇护下坐等父王驾崩。'});
    hp(d,'w_reims',{note:'1461年8月15日，三十八岁的路易十一在好人腓力护送下于兰斯加冕。'});
