    hp(d,'lb_worms',{left:1,note:'莱茵河谷酿酒与造纸重镇群，为古腾堡提供了螺旋压榨机与商业资本。'});
    hp(d,'lb_bruges',{left:1,note:'尼德兰商港迅速成为欧洲印刷品与版画集散中心。'});
