    hp(d,'lb_bruges',{left:1,note:'布鲁日：因兹温河道泥沙淤塞，外商纷纷迁往安特卫普。'});
    hp(d,'lb_vienna',{note:'马克西米利安一世坐镇奥地利与帝国，哈布斯堡尼德兰成为全帝国最富庶的税源。'});
