    hp(d,'ty1_lutter',{kind:'battle',left:1,note:'1626年8月吕特之战与德绍桥之战：蒂利与华伦斯坦大破丹麦军，一路反攻占领日德兰半岛。'});
    hp(d,'gh_lubeck',{note:'1629年5月丹麦被迫签《吕贝克和约》，保证不再插手德意志事务。'});
