    hp(d,'vp_corleone',{left:1,note:'1282年反法起义主力山城；19世纪以后成为近代西西里黑手党家族重镇。'});
    hp(d,'no_messina',{note:'1282年4月起义市民响应巴勒莫，清剿法军驻防官兵。'});
