    hp(d,'ko_malta',{kind:'battle',note:'1283年夏，劳里亚的罗杰在此击败安茹的普罗旺斯舰队。'});
    hp(d,'naples',{kind:'battle',note:'1284年6月5日，劳里亚的罗杰在此湾诱敌大胜，活捉安茹王储萨勒诺亲王查理。'});
    hp(d,'vp_girona',{kind:'battle',left:1,note:'1285年法王腓力三世率“阿拉贡十字军”围攻此城，染痢疾溃退、死于佩皮尼昂。'});
    hp(d,'vp_caltabellotta',{left:1,note:'1302年8月31日双方在此签和约，海岛与大陆正式裂成“两西西里”。'});
