    hp(d,'rf1_wittenberg',{left:1,note:'萨克森与黑森：诸侯改信新教后，将领地内数百座修道院地产充公归入邦君国库。'});
    hp(d,'gh_lubeck',{left:1,note:'北德自由市与丹麦、瑞典王室也纷纷改信路德宗，没收天主教庞大教产。'});
