    hp(d,'c_talas',{kind:'battle'});hp(d,'c_youzhou',{note:'范阳节度使安禄山755年在此起兵。'});
    hl(d,'亚俱罗（库法）：杜环见到汉人工匠','Kufa: Chinese craftsmen seen by Du Huan',32.03,44.4,HC.myc);
    hl(d,'吐蕃','Tibet',32.5,88.0,HC.war);
