    hp(d,'p_medina',{note:'阿拉伯人的奥斯、哈兹拉吉两部与几个犹太部落混居的绿洲。'});
    hp(d,'ar_khaybar',{note:'犹太人的椰枣绿洲。'});hp(d,'ar_najran',{note:'基督徒的城。'});
