    hp(d,'f_cherson',{left:1,note:'前5世纪后期，黑海南岸的赫拉克利亚人在克里米亚西南角所建。'});
    hp(d,'ea_tanais');
    hr(d,[[37.53,27.28],[39.4,26.2],[40.3,26.6],[41.05,29.0],[42.4,29.9],[44.6,30.6],[46.5,31.6]],HC.athens);
