    hp(d,'sl_hama',{kind:'battle',note:'1175年4月城外一战，萨拉丁打垮摩苏尔和阿勒颇的联军。'});
    hp(d,'sl_azaz',{kind:'battle',left:1,note:'1176年5月围城时刺客砍中萨拉丁的头，帽里的锁子甲救了命。'});
