    hp(d,'ko_krak',{note:'医院骑士团的骑士堡，最多驻兵约两千。'});
    hp(d,'ko_margat',{left:1,note:'1186年马扎尔家养不起，把它卖给医院骑士团。'});
    hp(d,'ko_damietta',{note:'1250年5月，茹安维尔在圣殿骑士团的船上劈箱取钱，凑路易九世的赎金。'});
    hr(d,[[48.85,2.35],[45.76,4.83],[43.3,5.37],[42.0,8.5],[39.5,12.0],[37.0,15.5],[35.5,20.0],[34.5,26.0],[33.6,31.0],[32.92,35.07]],HC.route);
