    hp(d,'ko_limassol',{note:'1291—1310年医院骑士团的总部在塞浦路斯。'});
    hp(d,'rhodes',{note:'1310年拿下罗得城；1522年被围半年后开城，1523年1月1日骑士团列队离开。'});
    hp(d,'ko_malta',{note:'1530年查理五世以每年一只猎鹰为租，把马耳他给了骑士团；1565年打退奥斯曼人。'});
