    hp(d,'uk7_mirebeau',{kind:'battle',note:'1202年7月阿瑟在此围困八十岁的祖母埃莉诺，约翰急行军突袭救出老母、生擒阿瑟。'});
    hp(d,'uk7_corfe',{left:1,note:'约翰将米拉博俘获的二十二名贵族骑士关押于科夫堡活活饿死。'});
