    hp(d,'pl_gaillard',{kind:'battle',note:'1204年3月6日腓力二世攻破加亚尔城堡，诺曼底防线崩溃。'});
    hp(d,'uk7_fontevraud',{left:1,note:'1204年4月1日八旬太后埃莉诺在此悲愤病逝，与亨利二世、理查一世同葬。'});
