    hp(d,'luoyi',{note:'东汉：以尚书台（内廷文书小机构）架空外朝三公。'});
    hp(d,'changan',{left:1,note:'隋唐：三省六部将相权一分为三，唐中后期以“同中书门下平章事”为实际宰相。'});
    hp(d,'jiankang',{note:'明废丞相设内阁大学士“票拟”；清雍正设军机处跪受笔录，相权彻底消灭。'});
